/**
 * Unit tests for PolygonsSet.computeGeometricalProperties.
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class PolygonsSet_computeGeometricalProperties_TriageGen2Test {

    private static class TestablePolygonsSet extends PolygonsSet {
        private Vector2D[][] vertices;
        private BSPTree<Euclidean2D> mockTree;

        public TestablePolygonsSet(Vector2D[][] vertices, BSPTree<Euclidean2D> tree) {
            super();
            this.vertices = vertices;
            this.mockTree = tree;
        }

        @Override
        public Vector2D[][] getVertices() {
            return vertices;
        }

        @Override
        protected BSPTree<Euclidean2D> getTree(boolean isInside) {
            return mockTree;
        }

        @Override
        public void computeGeometricalProperties() {
            super.computeGeometricalProperties();
        }
    }

    @Test
    public void testEmptyVertices_TreeCoversWholeSpace() {
        BSPTree<Euclidean2D> tree = mock(BSPTree.class);
        when(tree.getAttribute()).thenReturn(true);

        TestablePolygonsSet set = new TestablePolygonsSet(new Vector2D[0][0], tree);
        set.computeGeometricalProperties();

        assertEquals(Double.POSITIVE_INFINITY, set.getSize(), 0.0);
        assertEquals(Double.NaN, set.getBarycenter().getX(), 0.0);
    }

    @Test
    public void testEmptyVertices_TreeDoesNotCoverWholeSpace() {
        BSPTree<Euclidean2D> tree = mock(BSPTree.class);
        when(tree.getAttribute()).thenReturn(false);

        TestablePolygonsSet set = new TestablePolygonsSet(new Vector2D[0][0], tree);
        set.computeGeometricalProperties();

        assertEquals(0.0, set.getSize(), 0.0);
        assertEquals(new Vector2D(0, 0), set.getBarycenter());
    }

    @Test
    public void testOpenLoop_InfinitePolygon() {
        // v[0][0] == null signifies an open loop
        Vector2D[][] vertices = new Vector2D[1][1];
        vertices[0][0] = null;

        TestablePolygonsSet set = new TestablePolygonsSet(vertices, null);
        set.computeGeometricalProperties();

        assertEquals(Double.POSITIVE_INFINITY, set.getSize(), 0.0);
        assertEquals(Double.NaN, set.getBarycenter().getX(), 0.0);
    }

    @Test
    public void testClosedLoop_FiniteArea() {
        // Square: (0,0), (2,0), (2,2), (0,2)
        // Area = 4
        // Barycenter = (1,1)
        Vector2D[] loop = new Vector2D[]{
            new Vector2D(0, 0),
            new Vector2D(2, 0),
            new Vector2D(2, 2),
            new Vector2D(0, 2)
        };
        Vector2D[][] vertices = new Vector2D[][]{loop};

        TestablePolygonsSet set = new TestablePolygonsSet(vertices, null);
        set.computeGeometricalProperties();

        assertEquals(4.0, set.getSize(), 1e-9);
        assertEquals(1.0, set.getBarycenter().getX(), 1e-9);
        assertEquals(1.0, set.getBarycenter().getY(), 1e-9);
    }

    @Test
    public void testClosedLoop_NegativeSum_InfinitePolygon() {
        // Clockwise square (negative area/sum in this formula)
        // Square: (0,0), (0,2), (2,2), (2,0)
        Vector2D[] loop = new Vector2D[]{
            new Vector2D(0, 0),
            new Vector2D(0, 2),
            new Vector2D(2, 2),
            new Vector2D(2, 0)
        };
        Vector2D[][] vertices = new Vector2D[][]{loop};

        TestablePolygonsSet set = new TestablePolygonsSet(vertices, null);
        set.computeGeometricalProperties();

        assertEquals(Double.POSITIVE_INFINITY, set.getSize(), 0.0);
        assertEquals(Double.NaN, set.getBarycenter().getX(), 0.0);
    }

    @Test
    public void testMultipleLoops_FiniteArea() {
        // One outer square (0,0 to 4,4) and one inner hole (1,1 to 3,3)
        // Outer loop (CCW): (0,0), (4,0), (4,4), (0,4) -> Area 16, Barycenter (2,2)
        // Inner loop (CCW): (1,1), (3,1), (3,3), (1,3) -> Area 4, Barycenter (2,2)
        // Note: To subtract area in this specific algorithm implementation, 
        // the inner loop must be oriented such that sum is reduced.
        // In this code, sum is sum of (x0y1 - y0x1). 
        // For a hole to reduce area, it must be clockwise.

        Vector2D[] outer = new Vector2D[]{
            new Vector2D(0, 0), new Vector2D(4, 0), new Vector2D(4, 4), new Vector2D(0, 4)
        };
        Vector2D[] inner = new Vector2D[]{
            new Vector2D(1, 1), new Vector2D(1, 3), new Vector2D(3, 3), new Vector2D(3, 1)
        };

        Vector2D[][] vertices = new Vector2D[][]{outer, inner};

        TestablePolygonsSet set = new TestablePolygonsSet(vertices, null);
        set.computeGeometricalProperties();

        // Total Area = 16 - 4 = 12
        assertEquals(12.0, set.getSize(), 1e-9);
        // Barycenter remains (2,2) due to symmetry
        assertEquals(2.0, set.getBarycenter().getX(), 1e-9);
        assertEquals(2.0, set.getBarycenter().getY(), 1e-9);
    }
}
